enum class HostedIntentOperation {send,queue,steer};
enum class HostedIntentDisposition {prepared,accepted,rejected,not_submitted,uncertain,cancelled};
struct HostedClientBinding {std::string epoch,launch_fingerprint,profile_id{"default"},account_scope;};
struct HostedClientMarkerProof {AgentPersistReceipt persistence;bool workspace_v2{};};
