    static std::string preparation(const HostedClientGeneration& record,const std::string& id){return record.key.name()+":"+record.binding.epoch+":"+id;}
    static HostedClientIntent& intent(HostedClientGeneration& record,const std::string& id){const auto at=std::find_if(record.pending.begin(),record.pending.end(),[&](const auto& value){return value.delivery_id==id;});if(at==record.pending.end())throw std::runtime_error("The hosted input ID has no durable prepared intent");return *at;}
